/**
 * n8n Code / Function node
 * Replaces {DECISION_LOG} in meeting_notes_markdown with a formatted Markdown table.
 */

function escapeMD(s = "") {
  // Escape pipes and convert newlines in cell values to <br>
  return String(s)
    .replace(/\|/g, "\\|")
    .replace(/\r?\n/g, " <br> ")
    .trim();
}

function formatDate(d) {
  if (!d) return "";
  const iso = /^\d{4}-\d{2}-\d{2}$/;
  if (iso.test(d)) return d;
  const parsed = new Date(d);
  if (!isNaN(parsed)) {
    const y = parsed.getFullYear();
    const m = String(parsed.getMonth() + 1).padStart(2, "0");
    const day = String(parsed.getDate()).padStart(2, "0");
    return `${y}-${m}-${day}`;
  }
  return escapeMD(d);
}

function buildDecisionTable(decisions = []) {
  const header =
    "| **Decision** | **Owner** | **Date** | **Risk if Wrong** | **Follow-on Actions** |\n" +
    "|---|---|---|---|---|";

  const rows = decisions.map(d => {
    const title   = escapeMD(d.title);
    const owner   = escapeMD(d.owner);
    const date    = formatDate(d.date);
    const risk    = escapeMD(d.risk);
    const actions = escapeMD(d.actions);

    return `| ${title} | ${owner} | ${date} | ${risk} | ${actions} |`;
  });

  return [header, ...rows].join("\n");
}

return items.map(item => {
  const obj = item.json ?? {};
  const md  = obj.meeting_notes_markdown || "";
  const decisions = Array.isArray(obj.decisions) ? obj.decisions : [];

  const table = buildDecisionTable(decisions);

  let outputMD = md;

  if (md.includes("{DECISION_LOG}")) {
    outputMD = md.replace("{DECISION_LOG}", table);
  } else {
    // fallback if merge field missing
    const headingRegex = /(##\s*2\)\s*Key Decisions[^\n]*\n)/i;
    if (headingRegex.test(md)) {
      outputMD = md.replace(headingRegex, `$1\n${table}\n`);
    } else {
      outputMD = `${md}\n\n${table}`;
    }
  }

  return {
    json: {
      ...obj,
      decisions: undefined,
      meeting_notes_markdown: outputMD,
    },
  };
});

// Builds the <LIST OF CLIENTS & PROSPECTS> block for the Categorization Agent
// from the ClickUp BD Pipeline list (901113925326). Names, category and stage
// only: descriptions and contacts never leave ClickUp.
const CATEGORY_FIELD = '5a623c67-06b5-499a-b35b-a03ff52ed326'; // 🏷️ Category (labels)
const STAGE_FIELD = '797e8072-df53-457f-aa22-1f9802da933d'; // 🎢 Stage (drop-down)
const ORDER = ['Client', 'Prospect', 'Referrer', 'Collaborator', 'Influencer', 'Startup', 'Former', '3CV-Legacy'];

function field(task, id) {
  return (task.custom_fields || []).find(f => f.id === id);
}
function labels(f) {
  if (!f || !Array.isArray(f.value)) return [];
  const opts = (f.type_config && f.type_config.options) || [];
  return f.value.map(v => {
    const id = typeof v === 'object' && v !== null ? v.id : v;
    const o = opts.find(x => x.id === id);
    return o ? o.label : null;
  }).filter(Boolean);
}
function dropdown(f) {
  if (!f || f.value === null || f.value === undefined || f.value === '') return null;
  const opts = (f.type_config && f.type_config.options) || [];
  const o = opts.find(x => x.orderindex === Number(f.value) || x.id === f.value);
  return o ? o.name : null;
}

const groups = {};
for (const item of $input.all()) {
  const t = item.json;
  if (!t || !t.name || t.error) continue;
  const cats = labels(field(t, CATEGORY_FIELD));
  if (!cats.length) continue; // scheduling tasks and other non-relationship rows
  const stage = dropdown(field(t, STAGE_FIELD));
  const closed = t.status && String(t.status.type || t.status.status || '').toLowerCase() === 'closed';
  const detail = [stage, closed ? 'record closed' : null].filter(Boolean).join('; ');
  const primary = ORDER.find(c => cats.includes(c)) || cats[0];
  const others = cats.filter(c => c !== primary);
  const line = `- ${t.name}${others.length ? ` [also ${others.join(', ')}]` : ''}${detail ? ` — ${detail}` : ''}`;
  (groups[primary] = groups[primary] || []).push(line);
}

const sections = [...ORDER, ...Object.keys(groups).filter(c => !ORDER.includes(c))]
  .filter(c => groups[c])
  .map(c => `${c}:\n${groups[c].sort((a, b) => a.localeCompare(b)).join('\n')}`);

const client_list = sections.length
  ? sections.join('\n\n')
  : '(Client list unavailable: the BD Pipeline lookup returned nothing. Classify from the transcript.)';

return [{
  json: { ...$('Meeting Types').first().json, client_list },
  pairedItem: { item: 0 },
}];
